style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
/* ===============================
   GLOBAL BACKGROUND
   =============================== */
body, html {
  background: transparent !important;
  min-height: 100vh !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* Fixed wallpaper behind everything */
body::before {
  content: "";
  position: fixed;
  top: 0; right: 0; bottom: 0; left: 0;
  z-index: -1;
  background-image: url("https://wallpapers.com/images/high/white-nissan-skyline-gtr-r34-rear-jww3u9z2b1hk39w8.webp");
  background-position: center center;
  background-repeat: no-repeat;
  background-attachment: fixed;
  background-size: cover;
  pointer-events: none;
}

/* ===============================
   TRANSPARENT PANELS & MODALS
   =============================== */
#app, .modal, .card, .menu, .panel, 
.container-main, .page-content, .content, .container-fluid {
  background: rgba(255, 255, 255, 0.15) !important;
  backdrop-filter: blur(6px) !important;
  box-shadow: none !important;
  border: none !important;
}

/* ===============================
   DARK MODE SUPPORT
   =============================== */
.theme-dark, .rbx-body.theme-dark {
  background: rgba(0, 0, 0, 0.2) !important;
}

/* ===============================
   LIGHT MODE SUPPORT
   =============================== */
.theme-light, .rbx-body.theme-light {
  background: rgba(255, 255, 255, 0.15) !important;
}

/* ===============================
   FULL HEIGHT PAGE CONTENT
   =============================== */
.page-content, .content, .container-fluid {
  min-height: 100vh !important;
}
}
